using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with the default reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> => Type = {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18.5);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing
//    WeatherForecast is known, so this succeeds:
if (options.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? info))
    Console.WriteLine($"TryGet succeeded for {info!.Type.Name}");
else
    Console.WriteLine("TryGet failed for WeatherForecast (unexpected)");

// Now try with a source-gen context that only knows about WeatherForecast.
// Asking for int[] should return false instead of throwing.
var sgOptions = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (sgOptions.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
    Console.WriteLine($"TryGet succeeded for int[] => {arrayInfo!.Type.Name}");
else
    Console.WriteLine("TryGet correctly returned false for int[] (not in source-gen context)");

// --- Types ----------------------------------------------------------------
public record WeatherForecast(string City, double TempC);

[JsonSerializable(typeof(WeatherForecast))]
internal partial class SmallContext : JsonSerializerContext;

